const urls = ["https://jobs.target.com/", "https://target.wd5.myworkdayjobs.com/TargetCareers", "https://careers.target.com/"];
const res = [];
for (const u of urls) {
  try {
    const r = phi.goto(u);
    const o = phi.observe({ maxElements: 40 });
    res.push({ u, r, url: o.url, title: o.title, text: (o.text || "").slice(0, 600), nodes: o.nodes.map(n => `${n.ref}. ${n.role} "${n.name}"`).slice(0, 25) });
    if (o.url && !o.url.startsWith("chrome-error")) break;
  } catch (e) {
    res.push({ u, err: String(e).slice(0, 200) });
  }
}
return res;

